CREATE TABLE IF NOT EXISTS `jobs` (`id` int AUTO_INCREMENT NOT NULL, `serverId` int, `type` varchar(64) NOT NULL, `status` enum('queued','running','completed','failed','cancelled') NOT NULL DEFAULT 'queued', `payloadJson` text NOT NULL, `resultJson` text, `error` text, `startedAt` timestamp NULL, `finishedAt` timestamp NULL, `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT `jobs_id` PRIMARY KEY(`id`));
